INSERT INTO `reviews` (`id`, `score`, `description`, `order_id`, `product_id`, `created_at`, `updated_at`) VALUES
(1, 9, 'Quyển sách rất hay, tóm gọn kiến thức về MBA, để hiểu, thấm nhuần nội dung quyển sách, người đọc cần đang làm trong lĩnh vực kinh doanh để hiểu bối cảnh kinh doanh và liên kết nội dung trong quyển sách với bối cảnh kinh doanh thực tế.', 7, 86, '2024-12-10 11:08:51', NULL),
(2, 9, 'Bộ sách được thiết kế đẹp mắt, bìa sách in ấn rõ ràng, màu sắc trang nhã. Chất liệu giấy tốt, dày dặn và có độ trắng mịn, giúp người đọc dễ dàng theo dõi nội dung.', 7, 13, '2024-12-02 11:08:55', NULL),
(3, 10, 'Một số ví dụ trong sách còn xa lạ với văn hóa Việt Nam Sách tập trung vào kỹ năng tư duy, chưa đề cập đến kỹ năng mềm khác', 8, 3, '2024-12-01 11:09:00', NULL),
(4, 8, 'Sản phẩm đóng gói cẩn thận, sách được bọc rất kĩ. Giao hàng rất đầy đủ, mọi thứ đều rất hoàn hảo', 20, 95, '2024-12-05 11:09:02', NULL),
(5, 8, 'Shop đóng gói đẹp, giao hàng nhanh, sách có thẻ đánh dấu rất OK', 22, 67, '2024-12-22 11:08:58', NULL),
(6, 9, 'Giao nhanh, sách đẹp, mình rất thích lun á.', 23, 2, '2024-09-08 11:09:27', NULL),
(7, 9, 'Mình chưa đọc hết nên k chắc, nhưng nhìn sơ qua mục lục thì mình thấy khá hấp dẫn.', 24, 107, '2024-11-19 11:09:21', NULL),
(8, 9, 'Sách mới thơm lắm, ngửi ta nói nó phê Giấy cũng ok cũng gọi là chất lượng, giao hàng nhanh, có chống sốc các thứ nữa, mua được giá rẻ tận 2 cuốn hời quá ạ. Shop tuyệt vời', 27, 12, '2024-06-17 11:09:36', NULL),
(9, 8, 'Sách mới đẹp và hay ts nghĩ mình mua tặng bạn mình hy vọng là ngta sẽ thích. Lần đầu mua của shop cug an tâm về chất lượng vì sách mới mua tặng nên cẩn thạn xiu Mn mua đi mình đọc thays cũng hay đóng giis kỹ', 33, 108, '2024-07-14 11:09:32', NULL),
(10, 10, 'nhận đủ 3 cuốn đóng gói kỉ sách có bao bọc xiu rất sạch sẻ nguyên vẹn,', 35, 40, '2024-12-08 11:09:43', NULL),
(11, 8, 'Sách được bao gói 1 cách trân trọng, mình rất thích khi cầm 1 quyển sách được nâng niu, đó là sự tôn trọng tác giả, sẽ đọc', 37, 85, '2024-10-29 11:09:53', NULL),
(12, 10, 'Sách đẹp, đóng gói chắc chắn, chữ in rõ, mua được giá rẻ. Shop giao hàng nhanh nên rất hài lòng.', 38, 17, '2024-08-18 11:09:49', NULL),
(13, 9, 'Mình vô tình xem được video một c đọc sách này và review nên mình tò mò mua về đọc thử, ấn tượng của mình là Sbooks đóng gói kỹ, đẹp và có thư cảm ơn đồ lun.', 39, 135, '2024-09-22 11:09:59', NULL),
(14, 10, 'Cbi hàng nhanh, đóng hàng kỹ.', 40, 95, '2024-10-05 11:10:04', NULL),
(15, 10, 'Nhà sách có gửi kèm lời cảm ơn và thư ngỏ (rất chu đáo). Nội dung sách dễ hiểu, sách đẹp, in nét.', 40, 115, '2024-12-07 11:10:08', NULL),
(16, 8, 'Nội dung chưa xem, sẽ cập nhật, đóng gói cẩn thận, giao hàng nhanh, bìa sách ok, chất liệu giấy mình cho 8đ, xem review thấy rất hay nên mình tìm tòi mua về đọc thử, nếu cần loại nào nữa m sẽ đăt,', 41, 33, '2024-10-13 11:10:12', NULL),
(17, 10, 'Đã nhận được sách. Sách mới đẹp đóng gói cẩn thận bao bì bao quanh tốt ok. Có xấp bao lì xì và thư cảm ơn. Rất hài lòng với giá tiền lẫn chất lượng.', 44, 20, '2024-09-30 11:10:16', NULL),
(18, 9, 'Giao hàng khá nhanh, đóng gói cẩn thận nữa. Trong mỗi quyển sách đều có thẻ đánh dấu trang đọc đến. Chữ rất rõ nét, giấy chất lượng tốt. Lần sau sẽ tiếp tục ủng hộ cho shop', 45, 99, '2024-10-20 11:10:21', NULL),
(19, 9, 'Giao hàng nhanh lắm..mua sách cái không biết viết đánh giá sao luôn mà sách này không phải mua cho', 46, 103, '2024-08-11 11:11:20', NULL),
(20, 8, 'Giao hàng nhanh, đóng gói ổn, chắc chắn, bìa sách trơn bóng,', 46, 52, '2024-07-21 11:11:25', NULL),
(21, 9, 'Đóng hàng cẩn thận, chu đáo. Ship hàng nhanh.', 46, 36, '2024-12-09 11:11:17', NULL),
(22, 9, 'Đóng hàng đẹp gọn, k bị gấp góc. Nếu muốn thay đổi bản thân thì nên đầu tư kiến thức.', 46, 41, '2024-05-06 11:11:33', NULL),
(23, 9, 'Chưa đọc. Chất lượng giấy và chữ in đẹp, sắc nét. Đáng để mua. Sợ nhất nhiều shop in chữ mờ . Sẽ ủng hộ những cuốn sách tiếp theo', 59, 131, '2024-10-15 11:11:38', NULL),
(24, 9, 'OK nha rẻ vì mua seal tuyệt nha OK lắm nha OK lắm lắm luôn', 60, 98, '2024-07-07 11:11:29', NULL),
(25, 8, 'Giao hàng nhanh anh giao hàng thân thiện lần sau mình sẽ ủng hộ shop nha', 63, 28, '2023-12-05 11:11:43', NULL),
(26, 10, 'Đóng gói cẩn thận, giao hàng nhanh chóng, sách được bọc kỹ càng.', 64, 130, '2023-12-26 11:11:53', NULL);

